CREATE TABLE rv_job (id BINARY(16) PRIMARY KEY, queue VARCHAR(64) NOT NULL, kind VARCHAR(64) NOT NULL, payload MEDIUMBLOB NOT NULL, idempotency_key VARCHAR(128) NULL, state SMALLINT NOT NULL CHECK (state BETWEEN 0 AND 3), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), max_attempts INTEGER NOT NULL CHECK (max_attempts BETWEEN 1 AND 100), run_at DATETIME(6) NOT NULL, lease_token BINARY(16) NULL, lease_expires_at DATETIME(6) NULL, last_failure SMALLINT NULL CHECK (last_failure BETWEEN 1 AND 5), trace_parent VARCHAR(55) NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, completed_at DATETIME(6) NULL);
